-- ============================================================
-- 011 — FAQ thật của farm, giá lấy từ bảng tổng hợp
--
-- Hai nguồn, mỗi nguồn một việc:
--   FAQ_san_pham_Doc_Mo_Farm_final.xlsx  → 264 câu hỏi và câu trả lời
--   DanhSachSanPham_tonghop.xlsx         → giá của 28 mặt hàng FAQ nhắc tới
--
-- Giá KHÔNG viết cứng vào câu trả lời. Câu trả lời chứa ô trống {{gia}}, giá
-- được điền lúc gửi tin, đọc thẳng từ bảng products. Sửa giá ở /admin là mọi
-- câu trả lời đổi theo, không còn con số cũ nào sót lại trong 264 dòng này.
-- Luật chatbot số 2 của file FAQ cũng yêu cầu đúng điều đó: không dùng giá
-- lịch sử, phải tra nguồn hiện hành.
--
--   {{gia}}   luôn hiện giá    — câu hỏi giá, quy cách, còn hàng
--   {{gia1}}  chỉ hiện lần đầu — câu kỹ thuật (thành phần, cách dùng, bảo quản)
--
-- Cột name giữ tên khách hay gọi (vd "Dầu gội cao cấp Thư giãn cân bằng"),
-- name_vi giữ tên trong bảng giá ("Dầu gội cao cấp Relax Spa"). Tìm được cả
-- hai, báo giá theo tên chính thức.
-- ============================================================

-- Tám dòng seed lúc dựng khung là giá tôi bịa (xúc xích 85.000đ, thật là
-- 230.000đ). Tắt đi chứ không xoá — đơn cũ còn trỏ tới.
UPDATE products SET is_available = FALSE WHERE sku LIKE 'DMF-%';

ON CONFLICT (sku) DO UPDATE SET
  name = EXCLUDED.name, name_vi = EXCLUDED.name_vi, base_price = EXCLUDED.base_price,
  unit = EXCLUDED.unit, category = EXCLUDED.category, is_available = TRUE, updated_at = NOW();

-- FAQ. Cột ghi chú giữ nguyên cờ hành động của file gốc: bot chỉ được tự trả
-- lời dòng TU_DONG; TRA_CUU phải tra bảng giá/kho trước; CHUYEN_NGUOI thì gọi
-- người thật. Dầu xả thảo mộc để is_active = FALSE theo Luật số 8.
ON CONFLICT DO NOTHING;

-- ------------------------------------------------------------
-- Một chỗ hai nguồn nói khác nhau, farm đã chọn bên nào đúng.
--
-- Trà thảo mộc: file FAQ ghi túi 50g, bảng giá ghi gói 80gram giá 80.000đ.
-- Farm xác nhận bảng giá đúng. Nếu để nguyên, khách sẽ đọc được một câu tự
-- mâu thuẫn: "đóng túi 50g ạ. (80K/gói 80gram)".
-- ------------------------------------------------------------
UPDATE bot_lessons
SET answer = 'Trà thảo mộc đóng gói 80g ạ. ({{gia}})', updated_at = NOW()
WHERE product = 'Trà thảo mộc' AND answer LIKE '%50g%';
