INSERT INTO bot_lessons (question, answer, note, product, sku, sort_order, is_active) VALUES
($q$COMBO dầu gội + dầu tắm một cặp bao nhiêu ạ?$q$, $q$Combo gồm một chai dầu gội 480ml và một chai dầu tắm 480ml ạ. ({{gia}})$q$, $q$FAQ P05.2 · Quy cách · TU_DONG$q$, $q$COMBO dầu gội + dầu tắm$q$, $q$SP001703$q$, 2, TRUE),
($q$COMBO dầu gội + dầu tắm để được bao lâu ạ?$q$, $q$Mỗi chai có hạn sử dụng 12 tháng từ ngày sản xuất. Mình xem NSX và HSD riêng trên từng chai ạ. ({{gia1}})$q$, $q$FAQ P05.4 · Hạn sử dụng · TU_DONG$q$, $q$COMBO dầu gội + dầu tắm$q$, $q$SP001703$q$, 4, TRUE),
($q$COMBO dầu gội + dầu tắm bảo quản thế nào ạ?$q$, $q$Mình đậy nắp sau khi dùng và tránh để hai chai dưới ánh nắng trực tiếp ạ. ({{gia1}})$q$, $q$FAQ P05.5 · Bảo quản · TU_DONG$q$, $q$COMBO dầu gội + dầu tắm$q$, $q$SP001703$q$, 5, TRUE),
($q$COMBO dầu gội + dầu tắm làm từ gì ạ?$q$, $q$Combo gồm dầu gội thảo mộc và dầu tắm từ các loại dầu thực vật cùng tinh dầu sả. Farm có thể gửi thành phần chi tiết của từng chai ạ. ({{gia1}})$q$, $q$FAQ P05.6 · Thành phần · TU_DONG$q$, $q$COMBO dầu gội + dầu tắm$q$, $q$SP001703$q$, 6, TRUE),
($q$COMBO dầu gội + dầu tắm bao nhiêu ạ?$q$, $q$COMBO dầu gội + dầu tắm giá {{gia}} ạ.$q$, $q$FAQ P05.1 · Giá · TU_DONG$q$, $q$COMBO dầu gội + dầu tắm$q$, $q$SP001703$q$, 1, TRUE),
($q$Farm còn combo dầu gội + dầu tắm không ạ?$q$, $q$Tình trạng COMBO dầu gội + dầu tắm thay đổi theo từng đợt. Farm kiểm kho hiện tại rồi báo mình ngay ạ. ({{gia}})$q$, $q$FAQ P05.3 · Còn hàng · TRA_CUU_LIVE_HOAC_CHUYEN_NGUOI$q$, $q$COMBO dầu gội + dầu tắm$q$, $q$SP001703$q$, 3, TRUE),
($q$COMBO dầu gội + dầu tắm dùng thế nào ạ?$q$, $q$Farm cần kiểm lại hướng dẫn của chai dầu gội trong combo vì hai nhãn đang ghi khác nhau về việc pha loãng. Dầu tắm dùng với bông tắm rồi xả sạch ạ.$q$, $q$FAQ P05.7 · Cách dùng · CHUYEN_NGUOI$q$, $q$COMBO dầu gội + dầu tắm$q$, $q$SP001703$q$, 7, TRUE),
($q$Dầu gội cao cấp Rừng thảo mộc một chai bao nhiêu ạ?$q$, $q$Dầu gội cao cấp Rừng thảo mộc đóng chai 480ml ạ. ({{gia}})$q$, $q$FAQ P02.2 · Quy cách · TU_DONG$q$, $q$Dầu gội cao cấp Rừng thảo mộc$q$, $q$SP001915$q$, 2, TRUE),
($q$Dầu gội cao cấp Rừng thảo mộc để được bao lâu ạ?$q$, $q$Hạn sử dụng là 12 tháng từ ngày sản xuất. Mình xem thêm NSX và HSD in trên chai đang nhận ạ. ({{gia1}})$q$, $q$FAQ P02.4 · Hạn sử dụng · TU_DONG$q$, $q$Dầu gội cao cấp Rừng thảo mộc$q$, $q$SP001915$q$, 4, TRUE),
($q$Dầu gội cao cấp Rừng thảo mộc làm từ gì ạ?$q$, $q$Thành phần chính gồm nước, nhóm thảo mộc, chất làm sạch dịu, glycerin thực vật, nha đam lên men và tinh dầu yuzu, bưởi, bạc hà, phong lữ, oải hương, đàn hương, trầm hương ạ. ({{gia1}})$q$, $q$FAQ P02.6 · Thành phần · TU_DONG$q$, $q$Dầu gội cao cấp Rừng thảo mộc$q$, $q$SP001915$q$, 6, TRUE),
($q$Dầu gội cao cấp Rừng thảo mộc dùng thế nào ạ?$q$, $q$Mình làm ướt tóc, lấy lượng vừa đủ, massage tóc và da đầu trong vài phút rồi xả sạch với nước ạ. ({{gia1}})$q$, $q$FAQ P02.7 · Cách dùng · TU_DONG$q$, $q$Dầu gội cao cấp Rừng thảo mộc$q$, $q$SP001915$q$, 7, TRUE),
($q$Dầu gội Rừng thảo mộc là dạng nước, không đặc như dầu khác phải không?$q$, $q$Dầu gội Rừng thảo mộc có kết cấu khá lỏng và lượng bọt nhẹ hơn nhiều sản phẩm phổ biến. Mình làm ướt tóc, dùng lượng vừa đủ, massage rồi xả sạch ạ. ({{gia1}})$q$, $q$FAQ P02.8 · Kết cấu & cách dùng · TU_DONG$q$, $q$Dầu gội cao cấp Rừng thảo mộc$q$, $q$SP001915$q$, 8, TRUE),
($q$Dầu gội cao cấp Rừng thảo mộc bao nhiêu ạ?$q$, $q$Dầu gội cao cấp Rừng thảo mộc giá {{gia}} ạ.$q$, $q$FAQ P02.1 · Giá · TU_DONG$q$, $q$Dầu gội cao cấp Rừng thảo mộc$q$, $q$SP001915$q$, 1, TRUE),
($q$Farm còn dầu gội cao cấp rừng thảo mộc không ạ?$q$, $q$Tình trạng Dầu gội cao cấp Rừng thảo mộc thay đổi theo từng đợt. Farm kiểm kho hiện tại rồi báo mình ngay ạ. ({{gia}})$q$, $q$FAQ P02.3 · Còn hàng · TRA_CUU_LIVE_HOAC_CHUYEN_NGUOI$q$, $q$Dầu gội cao cấp Rừng thảo mộc$q$, $q$SP001915$q$, 3, TRUE),
($q$Kết quả kiểm nghiệm vi sinh của dầu gội này thế nào ạ?$q$, $q$Phiếu CASE ngày 28/10/2025 ghi tổng vi sinh của mẫu thử là 1,5 × 10⁶ CFU/g. Farm chuyển người phụ trách chất lượng giải thích kết quả và kiểm hồ sơ lô hiện hành ạ.$q$, $q$FAQ P02.20 · Kiểm nghiệm vi sinh · CHUYEN_NGUOI$q$, $q$Dầu gội cao cấp Rừng thảo mộc$q$, $q$SP001915$q$, 20, TRUE),
($q$Dầu gội này có kết quả kiểm nghiệm kim loại không ạ?$q$, $q$Mẫu thử ghi không phát hiện asen, thủy ngân và chì; ngưỡng phát hiện lần lượt là 0,02; 0,01; 0,5 mg/kg. Farm cần đối chiếu cùng kết quả vi sinh để giải thích đầy đủ ạ.$q$, $q$FAQ P02.21 · Kiểm nghiệm kim loại · CHUYEN_NGUOI$q$, $q$Dầu gội cao cấp Rừng thảo mộc$q$, $q$SP001915$q$, 21, TRUE),
($q$Dầu gội này đã có kết quả thử kích ứng da chưa ạ?$q$, $q$Bộ phiếu CASE của mẫu này hiện có kết quả kim loại và vi sinh, chưa có kết quả kích ứng da. Farm kiểm thêm hồ sơ rồi báo mình ạ.$q$, $q$FAQ P02.22 · Kiểm nghiệm kích ứng · CHUYEN_NGUOI$q$, $q$Dầu gội cao cấp Rừng thảo mộc$q$, $q$SP001915$q$, 22, TRUE),
($q$Dầu gội cao cấp Rừng thảo mộc bảo quản thế nào ạ?$q$, $q$Farm cần kiểm đúng hướng dẫn trên nhãn Dầu gội cao cấp Rừng thảo mộc hiện hành rồi báo cách bảo quản cho mình ạ.$q$, $q$FAQ P02.5 · Bảo quản · CHUYEN_NGUOI$q$, $q$Dầu gội cao cấp Rừng thảo mộc$q$, $q$SP001915$q$, 5, TRUE),
($q$Dầu gội cao cấp Thư giãn cân bằng một chai bao nhiêu ạ?$q$, $q$Dầu gội cao cấp Thư giãn cân bằng đóng chai 480ml ạ. ({{gia}})$q$, $q$FAQ P01.2 · Quy cách · TU_DONG$q$, $q$Dầu gội cao cấp Thư giãn cân bằng$q$, $q$SP001914$q$, 2, TRUE),
($q$Dầu gội cao cấp Thư giãn cân bằng để được bao lâu ạ?$q$, $q$Hạn sử dụng là 12 tháng từ ngày sản xuất. Mình xem thêm NSX và HSD in trên chai đang nhận ạ. ({{gia1}})$q$, $q$FAQ P01.4 · Hạn sử dụng · TU_DONG$q$, $q$Dầu gội cao cấp Thư giãn cân bằng$q$, $q$SP001914$q$, 4, TRUE),
($q$Dầu gội cao cấp Thư giãn cân bằng làm từ gì ạ?$q$, $q$Thành phần chính gồm nước, nhóm thảo mộc, chất làm sạch dịu, glycerin thực vật, nha đam lên men và tinh dầu cam bergamot, chanh xanh, bạc hà, phong lữ, oải hương, đàn hương ạ. ({{gia1}})$q$, $q$FAQ P01.6 · Thành phần · TU_DONG$q$, $q$Dầu gội cao cấp Thư giãn cân bằng$q$, $q$SP001914$q$, 6, TRUE),
($q$Dầu gội cao cấp Thư giãn cân bằng dùng thế nào ạ?$q$, $q$Mình làm ướt tóc, lấy lượng vừa đủ, massage tóc và da đầu trong vài phút rồi xả sạch với nước ạ. ({{gia1}})$q$, $q$FAQ P01.7 · Cách dùng · TU_DONG$q$, $q$Dầu gội cao cấp Thư giãn cân bằng$q$, $q$SP001914$q$, 7, TRUE),
($q$Dầu gội cao cấp Thư giãn cân bằng bao nhiêu ạ?$q$, $q$Dầu gội cao cấp Thư giãn cân bằng giá {{gia}} ạ.$q$, $q$FAQ P01.1 · Giá · TU_DONG$q$, $q$Dầu gội cao cấp Thư giãn cân bằng$q$, $q$SP001914$q$, 1, TRUE),
($q$Farm còn dầu gội cao cấp thư giãn cân bằng không ạ?$q$, $q$Tình trạng Dầu gội cao cấp Thư giãn cân bằng thay đổi theo từng đợt. Farm kiểm kho hiện tại rồi báo mình ngay ạ. ({{gia}})$q$, $q$FAQ P01.3 · Còn hàng · TRA_CUU_LIVE_HOAC_CHUYEN_NGUOI$q$, $q$Dầu gội cao cấp Thư giãn cân bằng$q$, $q$SP001914$q$, 3, TRUE),
($q$Kết quả kiểm nghiệm vi sinh của dầu gội này thế nào ạ?$q$, $q$Phiếu CASE ngày 28/10/2025 ghi tổng vi sinh của mẫu thử là 1,8 × 10⁷ CFU/g. Farm chuyển người phụ trách chất lượng giải thích kết quả và kiểm hồ sơ lô hiện hành ạ.$q$, $q$FAQ P01.20 · Kiểm nghiệm vi sinh · CHUYEN_NGUOI$q$, $q$Dầu gội cao cấp Thư giãn cân bằng$q$, $q$SP001914$q$, 20, TRUE),
($q$Dầu gội này có kết quả kiểm nghiệm kim loại không ạ?$q$, $q$Mẫu thử ghi không phát hiện asen, thủy ngân và chì; ngưỡng phát hiện lần lượt là 0,02; 0,01; 0,5 mg/kg. Farm cần đối chiếu cùng kết quả vi sinh để giải thích đầy đủ ạ.$q$, $q$FAQ P01.21 · Kiểm nghiệm kim loại · CHUYEN_NGUOI$q$, $q$Dầu gội cao cấp Thư giãn cân bằng$q$, $q$SP001914$q$, 21, TRUE),
($q$Dầu gội này đã có kết quả thử kích ứng da chưa ạ?$q$, $q$Bộ phiếu CASE của mẫu này hiện có kết quả kim loại và vi sinh, chưa có kết quả kích ứng da. Farm kiểm thêm hồ sơ rồi báo mình ạ.$q$, $q$FAQ P01.22 · Kiểm nghiệm kích ứng · CHUYEN_NGUOI$q$, $q$Dầu gội cao cấp Thư giãn cân bằng$q$, $q$SP001914$q$, 22, TRUE),
($q$Dầu gội cao cấp Thư giãn cân bằng bảo quản thế nào ạ?$q$, $q$Farm cần kiểm đúng hướng dẫn trên nhãn Dầu gội cao cấp Thư giãn cân bằng hiện hành rồi báo cách bảo quản cho mình ạ.$q$, $q$FAQ P01.5 · Bảo quản · CHUYEN_NGUOI$q$, $q$Dầu gội cao cấp Thư giãn cân bằng$q$, $q$SP001914$q$, 5, TRUE),
($q$Dầu gội có paraben hoặc hương nhân tạo không ạ?$q$, $q$Nhãn Farm cung cấp ghi không chứa paraben và không hương nhân tạo ạ. Nếu mình có dị ứng hoặc cần tránh chất cụ thể, Farm sẽ kiểm đúng nhãn lô hiện hành. ({{gia1}})$q$, $q$FAQ P03.12 · Thành phần · TU_DONG$q$, $q$Dầu gội thiên nhiên$q$, $q$SP000459$q$, 12, TRUE),
($q$Dầu gội đã kiểm nghiệm vi sinh chưa ạ?$q$, $q$Mẫu dầu gội có tổng vi sinh hiếu khí ưa nhiệt dưới 10 CFU/g. P. aeruginosa và C. albicans không phát hiện trong 0,1 g; S. aureus không phát hiện trong 1 g, theo phiếu VietLabs ạ. ({{gia1}})$q$, $q$FAQ P03.14 · Kiểm nghiệm vi sinh · TU_DONG$q$, $q$Dầu gội thiên nhiên$q$, $q$SP000459$q$, 14, TRUE),
($q$Dầu gội có kết quả kiểm nghiệm chì và asen không ạ?$q$, $q$Theo phiếu của mẫu dầu gội, chì và asen đều không phát hiện ở giới hạn định lượng 0,2 mg/kg. Kết quả này không có nghĩa là không chứa tuyệt đối ạ. ({{gia1}})$q$, $q$FAQ P03.15 · Kiểm nghiệm kim loại · TU_DONG$q$, $q$Dầu gội thiên nhiên$q$, $q$SP000459$q$, 15, TRUE),
($q$Kết quả thử kích ứng da của dầu gội thế nào ạ?$q$, $q$Theo phiếu VietLabs của mẫu dầu gội, mục kích ứng da ghi “không đáng kể”. Nếu da mình có dấu hiệu kích ứng, hãy ngưng dùng và báo Farm ạ. ({{gia1}})$q$, $q$FAQ P03.16 · Kiểm nghiệm kích ứng · TU_DONG$q$, $q$Dầu gội thiên nhiên$q$, $q$SP000459$q$, 16, TRUE),
($q$Kết quả kiểm nghiệm dầu gội có áp dụng cho mọi lô không ạ?$q$, $q$Không ạ. Kết quả chỉ phản ánh mẫu ghi trên phiếu VietLabs, không tự động đại diện cho mọi lô đang bán. Hồ sơ lô hiện hành cần được Farm kiểm riêng. ({{gia1}})$q$, $q$FAQ P03.17 · Phạm vi kiểm nghiệm · TU_DONG$q$, $q$Dầu gội thiên nhiên$q$, $q$SP000459$q$, 17, TRUE),
($q$Dầu gội thiên nhiên một chai bao nhiêu ạ?$q$, $q$Dầu gội thiên nhiên đóng chai 480ml ạ. ({{gia}})$q$, $q$FAQ P03.2 · Quy cách · TU_DONG$q$, $q$Dầu gội thiên nhiên$q$, $q$SP000459$q$, 2, TRUE),
($q$Sản phẩm dùng những chất làm sạch nào ạ?$q$, $q$Nhãn ghi disodium laureth sulfosuccinate, decyl glucoside và cocamidopropyl betaine, với nguồn gốc lần lượt từ dầu cọ, bắp và dầu dừa ạ. ({{gia1}})$q$, $q$FAQ P03.21 · Thành phần · TU_DONG$q$, $q$Dầu gội thiên nhiên$q$, $q$SP000459$q$, 21, TRUE),
($q$Dầu gội thiên nhiên để được bao lâu ạ?$q$, $q$Hạn sử dụng là 12 tháng từ ngày sản xuất. Mình xem NSX và HSD in trên chai ạ. ({{gia1}})$q$, $q$FAQ P03.4 · Hạn sử dụng · TU_DONG$q$, $q$Dầu gội thiên nhiên$q$, $q$SP000459$q$, 4, TRUE),
($q$Dầu gội thiên nhiên bảo quản thế nào ạ?$q$, $q$Mình đậy nắp sau khi dùng và tránh để chai dưới ánh nắng trực tiếp ạ. ({{gia1}})$q$, $q$FAQ P03.5 · Bảo quản · TU_DONG$q$, $q$Dầu gội thiên nhiên$q$, $q$SP000459$q$, 5, TRUE),
($q$Cho chị bảng thành phần dầu gội nha.$q$, $q$Theo nhãn, dầu gội có bồ kết, bồ hòn, muối biển, chanh, vỏ bưởi, cỏ mần trầu, sả java, hương nhu, sài đất, lá dâm bụt, gừng; cùng guar gum, glycerin thực vật, chất làm sạch nguồn gốc dầu cọ, bắp, dầu dừa và potassium sorbate ạ. ({{gia1}})$q$, $q$FAQ P03.8 · Thành phần · TU_DONG$q$, $q$Dầu gội thiên nhiên$q$, $q$SP000459$q$, 8, TRUE),
($q$Giá dầu gội bán riêng là bao nhiêu ạ?$q$, $q$Dầu gội thiên nhiên giá {{gia}} ạ.$q$, $q$FAQ P03.1 · Giá · TU_DONG$q$, $q$Dầu gội thiên nhiên$q$, $q$SP000459$q$, 1, TRUE),
($q$Farm còn dầu gội thiên nhiên không ạ?$q$, $q$Tình trạng Dầu gội thiên nhiên thay đổi theo từng đợt. Farm kiểm kho hiện tại rồi báo mình ngay ạ. ({{gia}})$q$, $q$FAQ P03.3 · Còn hàng · TRA_CUU_LIVE_HOAC_CHUYEN_NGUOI$q$, $q$Dầu gội thiên nhiên$q$, $q$SP000459$q$, 3, TRUE),
($q$Dầu gội thiên nhiên có những tinh dầu nào ạ?$q$, $q$Ảnh giới thiệu ghi tinh dầu hương nhu, bưởi và bạc hà, nhưng nhãn sau không liệt kê nhóm này. Farm cần kiểm đúng nhãn lô hiện hành trước khi xác nhận ạ.$q$, $q$FAQ P03.10 · Thành phần · CHUYEN_NGUOI$q$, $q$Dầu gội thiên nhiên$q$, $q$SP000459$q$, 10, TRUE),
($q$Dầu gội có chất bảo quản không ạ?$q$, $q$Nhãn sau ghi potassium sorbate; một ảnh giới thiệu còn ghi sodium benzoate. Farm cần kiểm đúng nhãn lô hiện hành trước khi xác nhận đầy đủ chất bảo quản ạ.$q$, $q$FAQ P03.11 · Thành phần · CHUYEN_NGUOI$q$, $q$Dầu gội thiên nhiên$q$, $q$SP000459$q$, 11, TRUE),
($q$Dầu gội có thật là 99% tự nhiên không ạ?$q$, $q$Nhãn có ghi 99% natural, nhưng hồ sơ Farm cung cấp chưa có cách tính hoặc chứng nhận cho tỷ lệ này. Farm cần kiểm căn cứ trước khi xác nhận ạ.$q$, $q$FAQ P03.13 · Tỷ lệ tự nhiên · CHUYEN_NGUOI$q$, $q$Dầu gội thiên nhiên$q$, $q$SP000459$q$, 13, TRUE),
($q$Farm gửi mình phiếu kiểm nghiệm dầu gội được không ạ?$q$, $q$Farm đã có phiếu VietLabs cho mẫu dầu gội, trả kết quả ngày 25/02/2025. Farm chuyển người phụ trách gửi bản đầy đủ và kiểm đúng sản phẩm mình cần ạ.$q$, $q$FAQ P03.18 · Phiếu kiểm nghiệm · CHUYEN_NGUOI$q$, $q$Dầu gội thiên nhiên$q$, $q$SP000459$q$, 18, TRUE),
($q$Sản phẩm có kết quả đo pH không ạ?$q$, $q$Hồ sơ hiện có chưa ghi kết quả pH của mẫu này. Farm cần kiểm thêm phiếu trước khi báo con số cụ thể ạ.$q$, $q$FAQ P03.20 · pH · CHUYEN_NGUOI$q$, $q$Dầu gội thiên nhiên$q$, $q$SP000459$q$, 20, TRUE),
($q$Tất cả nguyên liệu đều được trồng tại Farm phải không ạ?$q$, $q$Hồ sơ hiện có chưa xác nhận toàn bộ nguyên liệu đều do Farm trồng. Mình muốn biết nguồn gốc nguyên liệu nào để Farm kiểm cụ thể ạ?$q$, $q$FAQ P03.22 · Nguồn nguyên liệu · CHUYEN_NGUOI$q$, $q$Dầu gội thiên nhiên$q$, $q$SP000459$q$, 22, TRUE),
($q$Dầu gội thiên nhiên dùng thế nào ạ?$q$, $q$Hai nhãn Farm cung cấp ghi khác nhau về việc pha loãng. Farm cần kiểm đúng hướng dẫn trên chai hiện hành trước khi chỉ mình cách dùng ạ.$q$, $q$FAQ P03.7 · Cách dùng · CHUYEN_NGUOI$q$, $q$Dầu gội thiên nhiên$q$, $q$SP000459$q$, 7, TRUE),
($q$Chai dầu gội này có giúp giảm rụng tóc, kích thích mọc tóc không em?$q$, $q$Farm chưa có căn cứ để xác nhận sản phẩm giúp giảm rụng hay mọc tóc. Farm chuyển người phụ trách trao đổi thêm theo nhu cầu của mình ạ.$q$, $q$FAQ P03.9 · Công dụng sức khoẻ · CHUYEN_NGUOI$q$, $q$Dầu gội thiên nhiên$q$, $q$SP000459$q$, 9, TRUE),
($q$Dầu tắm có paraben hoặc hương nhân tạo không ạ?$q$, $q$Nhãn Farm cung cấp ghi không chứa paraben và không hương nhân tạo ạ. Nếu mình có dị ứng hoặc cần tránh chất cụ thể, Farm sẽ kiểm đúng nhãn lô hiện hành. ({{gia1}})$q$, $q$FAQ P04.10 · Thành phần · TU_DONG$q$, $q$Dầu tắm thiên nhiên$q$, $q$SP001508$q$, 10, TRUE),
