($q$Kết quả thử kích ứng da của dầu tắm thế nào ạ?$q$, $q$Theo phiếu VietLabs của mẫu dầu tắm, mục kích ứng da ghi “không đáng kể”. Nếu da mình có dấu hiệu kích ứng, hãy ngưng dùng và báo Farm ạ. ({{gia1}})$q$, $q$FAQ P04.14 · Kiểm nghiệm kích ứng · TU_DONG$q$, $q$Dầu tắm thiên nhiên$q$, $q$SP001508$q$, 14, TRUE),
($q$Kết quả kiểm nghiệm dầu tắm có áp dụng cho mọi lô không ạ?$q$, $q$Không ạ. Kết quả chỉ phản ánh mẫu ghi trên phiếu VietLabs, không tự động đại diện cho mọi lô đang bán. Hồ sơ lô hiện hành cần được Farm kiểm riêng. ({{gia1}})$q$, $q$FAQ P04.15 · Phạm vi kiểm nghiệm · TU_DONG$q$, $q$Dầu tắm thiên nhiên$q$, $q$SP001508$q$, 15, TRUE),
($q$Dầu tắm thiên nhiên một chai bao nhiêu ạ?$q$, $q$Dầu tắm thiên nhiên đóng chai 480ml ạ. ({{gia}})$q$, $q$FAQ P04.2 · Quy cách · TU_DONG$q$, $q$Dầu tắm thiên nhiên$q$, $q$SP001508$q$, 2, TRUE),
($q$Dầu tắm thiên nhiên để được bao lâu ạ?$q$, $q$Hạn sử dụng là 12 tháng từ ngày sản xuất. Mình xem NSX và HSD in trên chai ạ. ({{gia1}})$q$, $q$FAQ P04.4 · Hạn sử dụng · TU_DONG$q$, $q$Dầu tắm thiên nhiên$q$, $q$SP001508$q$, 4, TRUE),
($q$Dầu tắm thiên nhiên bảo quản thế nào ạ?$q$, $q$Mình đậy nắp sau khi dùng và tránh để chai dưới ánh nắng trực tiếp ạ. ({{gia1}})$q$, $q$FAQ P04.5 · Bảo quản · TU_DONG$q$, $q$Dầu tắm thiên nhiên$q$, $q$SP001508$q$, 5, TRUE),
($q$Dầu tắm thiên nhiên làm từ gì ạ?$q$, $q$Theo nhãn, dầu tắm có dầu olive, dầu dừa, dầu cọ, dầu castor, KOH, tinh dầu sả, xanthan gum, glycerin thực vật và chất làm sạch có nguồn gốc từ dầu cọ, bắp, dầu dừa ạ. ({{gia1}})$q$, $q$FAQ P04.6 · Thành phần · TU_DONG$q$, $q$Dầu tắm thiên nhiên$q$, $q$SP001508$q$, 6, TRUE),
($q$Dầu tắm thiên nhiên dùng thế nào ạ?$q$, $q$Mình làm ướt cơ thể, cho lượng vừa đủ vào bông tắm, tạo bọt, massage nhẹ rồi xả sạch với nước ạ. ({{gia1}})$q$, $q$FAQ P04.7 · Cách dùng · TU_DONG$q$, $q$Dầu tắm thiên nhiên$q$, $q$SP001508$q$, 7, TRUE),
($q$Dầu tắm thiên nhiên bao nhiêu ạ?$q$, $q$Dầu tắm thiên nhiên giá {{gia}} ạ.$q$, $q$FAQ P04.1 · Giá · TU_DONG$q$, $q$Dầu tắm thiên nhiên$q$, $q$SP001508$q$, 1, TRUE),
($q$Farm còn dầu tắm thiên nhiên không ạ?$q$, $q$Tình trạng Dầu tắm thiên nhiên thay đổi theo từng đợt. Farm kiểm kho hiện tại rồi báo mình ngay ạ. ({{gia}})$q$, $q$FAQ P04.3 · Còn hàng · TRA_CUU_LIVE_HOAC_CHUYEN_NGUOI$q$, $q$Dầu tắm thiên nhiên$q$, $q$SP001508$q$, 3, TRUE),
($q$Dầu tắm có thật là 96% tự nhiên không ạ?$q$, $q$Nhãn có ghi 96% natural, nhưng hồ sơ Farm cung cấp chưa có cách tính hoặc chứng nhận cho tỷ lệ này. Farm cần kiểm căn cứ trước khi xác nhận ạ.$q$, $q$FAQ P04.11 · Tỷ lệ tự nhiên · CHUYEN_NGUOI$q$, $q$Dầu tắm thiên nhiên$q$, $q$SP001508$q$, 11, TRUE),
($q$Farm gửi mình phiếu kiểm nghiệm dầu tắm được không ạ?$q$, $q$Farm đã có phiếu VietLabs cho mẫu dầu tắm, trả kết quả ngày 25/02/2025. Farm chuyển người phụ trách gửi bản đầy đủ và kiểm đúng sản phẩm mình cần ạ.$q$, $q$FAQ P04.16 · Phiếu kiểm nghiệm · CHUYEN_NGUOI$q$, $q$Dầu tắm thiên nhiên$q$, $q$SP001508$q$, 16, TRUE),
($q$Tỷ lệ các thành phần trong dầu tắm là bao nhiêu ạ?$q$, $q$Các ảnh Farm cung cấp ghi tỷ lệ tinh dầu và chất bảo quản chưa thống nhất, đồng thời tổng tỷ lệ trên nhãn chưa hợp lý. Farm cần kiểm công thức đã duyệt trước khi xác nhận ạ.$q$, $q$FAQ P04.8 · Tỷ lệ thành phần · CHUYEN_NGUOI$q$, $q$Dầu tắm thiên nhiên$q$, $q$SP001508$q$, 8, TRUE),
($q$Dầu tắm có chất bảo quản không ạ?$q$, $q$Nhãn sau không liệt kê chất bảo quản, nhưng ảnh giới thiệu ghi potassium sorbate và sodium benzoate. Farm cần kiểm đúng nhãn lô hiện hành trước khi xác nhận ạ.$q$, $q$FAQ P04.9 · Thành phần · CHUYEN_NGUOI$q$, $q$Dầu tắm thiên nhiên$q$, $q$SP001508$q$, 9, TRUE),
($q$Dầu xả thảo mộc giá bao nhiêu ạ?$q$, $q$Sản phẩm này đang chờ Farm hoàn thiện và xác nhận thông tin. Farm chưa nhận đặt hàng; khi có thông tin chính thức sẽ báo mình ạ.$q$, $q$FAQ P29.1 · Giá · CHUA_BAT_BOT$q$, $q$Dầu xả thảo mộc$q$, $q$$q$, 1, FALSE),
($q$Dầu xả thảo mộc một gói hoặc chai bao nhiêu ạ?$q$, $q$Sản phẩm này đang chờ Farm hoàn thiện và xác nhận thông tin. Farm chưa nhận đặt hàng; khi có thông tin chính thức sẽ báo mình ạ.$q$, $q$FAQ P29.2 · Quy cách · CHUA_BAT_BOT$q$, $q$Dầu xả thảo mộc$q$, $q$$q$, 2, FALSE),
